const html = $input.first().json.body;
const url = 'https://vnexpress.net';
const statusCode = 200;

// Helper: get attribute from tag string
function getAttr(tag, attr) {
  const re = new RegExp(attr + '=["\']([^"\']*)["\']', 'i');
  const m = tag.match(re);
  return m ? m[1] : null;
}

// Helper: get all matches of a regex
function matchAll(str, re) {
  const results = [];
  let m;
  while ((m = re.exec(str)) !== null) results.push(m);
  return results;
}

// Title
const titleMatch = html.match(/<title[^>]*>(.*?)<\/title>/is);
const title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : '';

// Meta tags
function getMeta(name) {
  const re = new RegExp('<meta[^>]*name=["\']' + name + '["\'][^>]*>', 'i');
  const m = html.match(re);
  return m ? (getAttr(m[0], 'content') || '') : '';
}
function getOg(prop) {
  const re = new RegExp('<meta[^>]*property=["\']' + prop + '["\'][^>]*>', 'i');
  const m = html.match(re);
  return m ? (getAttr(m[0], 'content') || '') : '';
}

const metaDesc = getMeta('description');
const metaKeywords = getMeta('keywords');
const viewport = getMeta('viewport');
const robots = getMeta('robots');
const ogTitle = getOg('og:title');
const ogDesc = getOg('og:description');
const ogImage = getOg('og:image');
const ogUrl = getOg('og:url');

// Charset
const charsetMatch = html.match(/<meta[^>]*charset=["']?([^"'\s>]+)/i);
const charset = charsetMatch ? charsetMatch[1] : 'utf-8';

// Canonical
const canonicalMatch = html.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']*)["']/i);
const canonical = canonicalMatch ? canonicalMatch[1] : '';

// Favicon
const faviconMatch = html.match(/<link[^>]*rel=["'][^"']*icon[^"']*["'][^>]*href=["']([^"']*)["']/i);
const favicon = faviconMatch ? faviconMatch[1] : '';

// Headings
function getHeadings(tag) {
  const re = new RegExp('<' + tag + '[^>]*>(.*?)<\/' + tag + '>', 'gis');
  return matchAll(html, re).map(m => m[1].replace(/<[^>]+>/g, '').trim()).filter(t => t);
}
const h1 = getHeadings('h1');
const h2 = getHeadings('h2');
const h3 = getHeadings('h3');

// Links
const linkMatches = matchAll(html, /<a[^>]*href=["']([^"']*)["']/gi);
const links = linkMatches.map(m => m[1]);
const internalLinks = links.filter(l => l.startsWith('/') || l.includes('vnexpress.net')).length;

// Images
const imgTags = matchAll(html, /<img[^>]*>/gi);
const images = imgTags.map(m => getAttr(m[0], 'src')).filter(Boolean);
const imagesWithAlt = imgTags.filter(m => { const a = getAttr(m[0], 'alt'); return a && a.length > 0; }).length;

// Word count (strip tags from body)
const bodyMatch = html.match(/<body[^>]*>(.*)<\/body>/is);
let bodyText = '';
if (bodyMatch) {
  bodyText = bodyMatch[1].replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
const wordCount = bodyText.split(/\s+/).filter(w => w.length > 0).length;

return [{
  json: {
    url,
    status_code: statusCode,
    title,
    title_length: title.length,
    meta_description: metaDesc,
    meta_description_length: metaDesc.length,
    meta_keywords: metaKeywords,
    og_title: ogTitle,
    og_description: ogDesc,
    og_image: ogImage,
    og_url: ogUrl,
    canonical_url: canonical,
    favicon,
    viewport,
    charset,
    robots_meta: robots,
    h1_tags: JSON.stringify(h1),
    h1_count: h1.length,
    h2_tags: JSON.stringify(h2),
    h2_count: h2.length,
    h3_tags: JSON.stringify(h3),
    h3_count: h3.length,
    total_links: links.length,
    internal_links: internalLinks,
    external_links: links.length - internalLinks,
    total_images: images.length,
    images_with_alt: imagesWithAlt,
    images_without_alt: images.length - imagesWithAlt,
    word_count: wordCount,
    links_json: JSON.stringify(links.slice(0, 500)),
    images_json: JSON.stringify(images.slice(0, 200)),
    crawled_at: new Date().toISOString()
  }
}];

const inserted = $input.first().json;
const crawlData = $('Extract & Transform').first().json;

return [{
  json: {
    success: true,
    message: 'Crawl completed and saved to PostgreSQL',
    data: {
      id: inserted.id,
      url: crawlData.url,
      title: crawlData.title,
      title_length: crawlData.title_length,
      meta_description: crawlData.meta_description,
      meta_description_length: crawlData.meta_description_length,
      h1_count: crawlData.h1_count,
      h2_count: crawlData.h2_count,
      h3_count: crawlData.h3_count,
      total_links: crawlData.total_links,
      internal_links: crawlData.internal_links,
      external_links: crawlData.external_links,
      total_images: crawlData.total_images,
      images_with_alt: crawlData.images_with_alt,
      images_without_alt: crawlData.images_without_alt,
      word_count: crawlData.word_count,
      crawled_at: crawlData.crawled_at
    }
  }
}];
